// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount <= 10000 ether); // bound for practical fuzzing
        vm.assume(collectAmount <= 10000 ether);

        // Set up minimal required conditions
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit some tokens
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before collect
        uint256 balanceBefore = c.balances(caller);

        // Attempt collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 balanceAfter = c.balances(caller);

        // General rule: balance should never decrease by more than collectAmount (if successful) or should stay same (if reverted)
        assertTrue(balanceAfter >= balanceBefore - collectAmount, "Balance decreased by more than requested amount");
    }
}

