pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Assume addresses are valid
        vm.assume(caller != address(0));

        // Initialize contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect with the given amount
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record balance after Collect
        uint256 balanceAfter = c.balances(caller);

        // The rule: if Collect succeeded (no revert), then the balance should not have decreased by more than the requested amount
        // This ensures no underflow: balanceAfter should be >= balanceBefore - collectAmount or >= 0
        if (success) {
            assertTrue(balanceAfter >= balanceBefore || balanceAfter >= balanceBefore - collectAmount, "Balance decreased more than allowed");
        }
    }
}

