pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        // Bound inputs to reasonable ranges (avoid overflow in sum calculations)
        minSum = bound(minSum, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, 1e30);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund the caller with some ETH (if needed for deposit)
        vm.deal(caller, depositAmount);

        // Pre-state: compute total balance of all addresses in contract
        // Since we don't have an iterator, we'll track total_balance_after calls.
        // For simplicity, we track the sum of all balances via a mapping we can compute.
        // But we only have access to balances via the public getter.
        // Instead, we'll just check that the caller's balance doesn't exceed total ETH deposited.
        // Actually, we can check: after Collect, the sum of all balances should be <= sum of all deposits.
        // That's too complex. Let's use a simpler property: 
        // After Collect, the caller's balance should be >= 0 (no underflow) — but that's already tried.
        // 
        // New property: The contract's ETH balance after Collect should never exceed the total ETH received via Deposit.
        // But we can't track total deposits easily. 
        // 
        // Let's use a different property: After Collect, the caller's balance should not exceed their total deposits.
        // But we need to know total deposits. 
        // 
        // Simpler: After a successful Collect, the caller's balance after Collect should be <= their balance before Collect.
        // That is always true for reference (since it subtracts correctly), but for buggy version, it might be violated if underflow occurs (balance becomes huge).
        // Actually, the buggy version removes the balance check, so underflow can cause caller's balance to become a huge number (due to underflow).
        // So property: After Collect, the caller's balance should be less than or equal to their balance before Collect.

        // Record caller's balance before any action
        uint256 callerBalanceBefore = c.balances(caller);

        // Make a deposit (so caller has some balance to potentially collect)
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceAfterDeposit = c.balances(caller);

        // Now call Collect
        vm.prank(caller);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 callerBalanceAfter = c.balances(caller);

        // General rule: If Collect succeeded, the caller's balance after should be <= their balance before Collect (i.e., before the call)
        // If Collect reverted, then balance should remain unchanged (= balanceAfterDeposit)
        if (ok) {
            assertTrue(callerBalanceAfter <= balanceAfterDeposit, "Balance increased after successful Collect");
        } else {
            assertTrue(callerBalanceAfter == balanceAfterDeposit, "Balance changed after reverted Collect");
        }
    }
}

