pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 minSum, uint256 _am) public {
        // Bound deposit to avoid overflow
        deposit = bound(deposit, 0, 1e30);
        // Avoid zero MinSum to simplify (non-zero MinSum is required for collect)
        vm.assume(minSum > 0 && minSum <= 1e30);
        // Set MinSum via admin (any address can call because initial check is only once)
        c.SetMinSum(minSum);
        c.Initialized();
        // Ensure caller has enough balance to meet MinSum for Collect
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();
        // Now try to collect, but restrict _am to avoid underflow in reference
        vm.assume(_am <= deposit && _am >= 0);
        uint256 balanceBefore = c.balances(caller);
        // Record whether Collect reverts
        bool reverted;
        vm.prank(caller);
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = c.balances(caller);
        // General rule: If Collect did not revert, then balance decreased by exactly _am
        // If it reverted, balance unchanged
        // In the buggy version, balance could decrease even when _am > deposit, violating this
        assertTrue(reverted ? balanceAfter == balanceBefore : balanceAfter == balanceBefore - _am);
    }
}

