pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2, uint256 minSum, uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Bound inputs to avoid overflow
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2);
        deposit1 = bound(deposit1, 0, 1e18);
        deposit2 = bound(deposit2, 0, 1e18);
        minSum = bound(minSum, 0, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund test accounts
        vm.deal(caller1, deposit1);
        vm.deal(caller2, deposit2);

        // Deposit from both callers
        vm.prank(caller1);
        c.Deposit{value: deposit1}();
        vm.prank(caller2);
        c.Deposit{value: deposit2}();

        // Try to collect from caller1
        vm.prank(caller1);
        (bool ok,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        if (ok) {
            // Only if collect succeeded, sum of balances <= contract balance
            uint256 sumBalances = c.balances(caller1) + c.balances(caller2);
            assertTrue(sumBalances <= address(c).balance, "Sum of balances exceeds contract balance");
        } else {
            // If collect reverted, balances unchanged, sum should still respect the invariant
            uint256 sumBalances = c.balances(caller1) + c.balances(caller2);
            assertTrue(sumBalances <= address(c).balance, "Sum of balances exceeds contract balance after revert");
        }
    }
}

