pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 initialBalance, uint256 minSum, uint256 amount) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(initialBalance >= minSum && initialBalance >= amount && amount > 0);

        // Initialize with min sum
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund the caller
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record old balance
        uint256 oldBalance = c.balances(caller);

        // Perform Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        // Rule: if Collect succeeded, caller's balance decreased by exactly amount
        if (success) {
            assertTrue(c.balances(caller) == oldBalance - amount, "Balance should decrease by exactly the amount");
        } else {
            // If reverted, balance should remain unchanged
            assertTrue(c.balances(caller) == oldBalance, "Balance unchanged on revert");
        }
    }
}

