contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 withdrawAmount) public {
        // Bound initialBalance to avoid overflow in deposit (balances + msg.value >= balances)
        vm.assume(initialBalance < type(uint256).max / 2);
        // Bound withdrawAmount to be <= initialBalance and non-zero for meaningful checks
        vm.assume(withdrawAmount > 0 && withdrawAmount <= initialBalance);

        // Set up: initialize the contract, fund caller, deposit
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.SetMinSum(0); // Ensure MinSum is 0 so Collect is always allowed
        c.Initialized();
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Execute Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        if (success) {
