    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 initialBalance, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        minSum = bound(minSum, 0, 1e18);
        initialBalance = bound(initialBalance, 0, 1e18);
        collectAmount = bound(collectAmount, 0, 1e18);

        // Setup: initialize the contract, set minSum, and fund the caller
        vm.prank(address(0xdead));
        c.SetMinSum(minSum);
        vm.prank(address(0xbeef));
        c.SetLogFile(address(0x1234));
        vm.prank(address(0xface));
        c.Initialized();

        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Try to collect
        vm.deal(caller, 0); // ensure caller has no extra ETH
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // The general rule: If Collect reverts (e.g., because MinSum or log assignment fails), balance is unchanged
        // In reference C, SetLogFile works correctly so revert only happens if conditions are not met
        // In mutant M, SetLogFile sets Log = address(0), causing revert in Collect inside Log.AddMessage
        // So the invariant: if the call reverted, balance must be unchanged
        if (!success) {
            assertTrue(c.balances(caller) == balanceBefore, "Balance changed on revert");
        }
    }
}

