pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 am, uint256 depositAmount, uint256 minSum) public {
        vm.assume(am <= type(uint256).max / 2);
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(minSum <= type(uint256).max / 2);

        // Initialize and fund
        c.SetMinSum(minSum);
        c.SetLogFile(address(0)); // will be overwritten by reference but not by buggy
        c.Initialized();

        // Deposit so caller has balance
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record log length before Collect
        uint lenBefore = c.Log().HistoryLength();

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));

        // Property: if Collect succeeded (caller had enough balance), log length increased by 1
        // This holds on reference because Log->AddMessage is called; on buggy it breaks because Log is address(0)
        if (success) {
            uint lenAfter = lenBefore; // need to get from LogFile, but Log is private? Actually Log is public so we can get LogFile address
            // But we cannot get History length directly from C; we need to get LogFile address via c.Log()
            // Then call LogFile's History length getter
            address logAddr = address(c.Log());
            if (logAddr != address(0)) {
                (bool ok, bytes memory data) = logAddr.staticcall(abi.encodeWithSignature("HistoryLength()"));
                if (ok) {
                    lenAfter = abi.decode(data, (uint256));
                }
            }
            assertTrue(lenAfter == lenBefore + 1, "History length should increase by 1");
        }
    }
}

