pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, address caller) public {
        // Set up: initialize, set MinSum to 0, set log to a real LogFile
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Fund caller with enough ETH
        uint256 balance = 1 ether;
        vm.deal(caller, balance);

        // Deposit some ETH from caller
        vm.prank(caller);
        c.Deposit{value: balance / 2}();

        // Bound am to be at most deposited amount
        uint256 deposit = balance / 2;
        vm.assume(am <= deposit);

        // Get Log address and length before Collect
        ILogFile log = ILogFile(c.Log());
        uint256 lenBefore = log.HistoryLength();

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        // Check: if success, History length increased by 1; if revert, unchanged
        uint256 lenAfter = log.HistoryLength();
        assertTrue(success ? (lenAfter == lenBefore + 1) : (lenAfter == lenBefore));
    }
}

interface ILogFile {
    function HistoryLength() external view returns (uint256);
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

